def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > 250:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 8.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    desperation = 0
    if hp <= 2:
        desperation += 3
    elif hp <= 4:
        desperation += 2
    elif hp <= 6:
        desperation += 1

    if no_water_days >= 2:
        desperation += 3
    elif no_water_days >= 1:
        desperation += 2

    if tight_supply:
        desperation += 1

    if day >= 8:
        desperation += 1

    if desperation >= 5:
        bid = max(62.0, high_prev + 3.0, avg_prev + 6.0)
    elif desperation >= 3:
        bid = max(42.0, avg_prev * 0.72, high_prev * 0.55)
    else:
        if loose_supply and high_prev >= 120:
            bid = 9.0
        elif loose_supply:
            bid = 16.0
        elif tight_supply:
            bid = max(24.0, avg_prev * 0.38)
        else:
            bid = max(18.0, avg_prev * 0.28)

    if rich_opp >= 1 and desperation <= 2:
        bid *= 0.9
    if urgent_opp >= 2 and desperation >= 3:
        bid *= 1.08

    if hp >= 8 and no_water_days == 0 and high_prev >= 140:
        bid = min(bid, 12.0)

    reserve = 0.0
    if day <= 7:
        reserve = 35.0
    elif day <= 9:
        reserve = 15.0

    max_affordable = max(0.0, budget - reserve)
    if desperation >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine max possible winners
    max_winners = int(supply // WATER_REQ)

    # Analyze yesterday's bids from opponents
    yesterday_bids = []
    for opp_id, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid if no info
    if not yesterday_bids:
        if hp <= 2 or no_water_days > 0:
            return min(budget, DAILY_SALARY * 0.95)
        return min(budget, DAILY_SALARY * 0.5)

    max_prev = max(yesterday_bids)
    # Check if Cindy (high budget) had a very high bid
    cindy_prev = None
    if 'Cindy' in alive_opponents:
        prev_c = alive_opponents['Cindy'].get('previous_trace', {})
        if prev_c:
            cindy_prev = prev_c.get('bid')

    # Adjust based on supply and urgency
    if max_winners >= 2:
        # Multiple winners possible: target second place
        target_bid = max(DAILY_SALARY * 0.6, max_prev + 1.0)
        if cindy_prev and cindy_prev > DAILY_SALARY * 1.2:
            # Cindy dominates, don't waste budget
            target_bid = min(target_bid, DAILY_SALARY * 0.7)
        if hp <= 2 or no_water_days > 0:
            target_bid = max(target_bid, DAILY_SALARY * 0.9)
    else:
        # Only one winner: must outbid others if necessary
        target_bid = DAILY_SALARY * 0.8
        if max_prev > target_bid:
            target_bid = max_prev + 2.0
        if hp <= 2 or no_water_days > 0:
            target_bid = max(target_bid, DAILY_SALARY * 0.95)
        # If Cindy likely to bid high, avoid overspending
        if cindy_prev and cindy_prev > DAILY_SALARY * 1.1:
            target_bid = min(target_bid, DAILY_SALARY * 0.5)

    # Cap at budget
    bid = min(budget, target_bid)
    # Ensure non-negative and at least 1 to participate
    return max(1.0, bid)
